import{_ as e,C as o,c as a,o as s,j as t,G as r,a0 as i,a as n}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Depoimentos de jogadores","description":"","frontmatter":{},"headers":[],"relativePath":"pt/testimonials.md","filePath":"pt/testimonials.md"}');const m=e({name:"pt/testimonials.md"},[["render",function(e,u,m,d,c,l){const p=o("AdBanner"),q=o("AdInArticle");return s(),a("div",null,[u[0]||(u[0]=t("h1",{id:"depoimentos-de-jogadores",tabindex:"-1"},[n("Depoimentos de jogadores "),t("a",{class:"header-anchor",href:"#depoimentos-de-jogadores","aria-label":'Permalink to "Depoimentos de jogadores"'},"​")],-1)),r(p),u[1]||(u[1]=i('<p>Depoimentos reais de jogadores de elite de petanca que utilizaram os recursos da Pétanque Academy para aprimorar seu jogo mental e desempenho em competições.</p><div class="tip custom-block"><p class="custom-block-title">Autêntico e Anônimo</p><p>Esses depoimentos representam o feedback genuíno de jogadores de diversos níveis competitivos. Todos os depoimentos são anônimos para proteger a privacidade dos jogadores e incentivar o compartilhamento honesto.</p></div><h2 id="competidores-regionais-e-nacionais" tabindex="-1">Competidores regionais e nacionais <a class="header-anchor" href="#competidores-regionais-e-nacionais" aria-label="Permalink to &quot;Competidores regionais e nacionais&quot;">​</a></h2><h3 id="quot-a-estrutura-do-coach-interior-mudou-tudo-quot" tabindex="-1">&quot;A estrutura do Coach Interior mudou tudo&quot; <a class="header-anchor" href="#quot-a-estrutura-do-coach-interior-mudou-tudo-quot" aria-label="Permalink to &quot;&amp;quot;A estrutura do Coach Interior mudou tudo&amp;quot;&quot;">​</a></h3><blockquote><p>&quot;Jogo petanca competitivamente há 12 anos e achava que sabia tudo sobre o esporte. Mas eu era meu pior inimigo — me criticava constantemente após cada erro. A estrutura &#39;Treinador Interior vs. Crítico Interior&#39;, do módulo Força Mental, me proporcionou uma maneira completamente diferente de conversar comigo mesmo durante as competições.&quot;</p><p><em>Em dois meses, meus colegas de equipe notaram a diferença. Eu estava mais calmo, me recuperava mais rápido de arremessos ruins e realmente voltei a gostar de competir. Fiquei em 3º lugar no regional este ano — meu melhor resultado até hoje.</em></p></blockquote><p><strong>— Campeão Regional, França</strong></p><hr><h3 id="quot-finalmente-alguem-que-entende-de-desenvolvimento-de-elite-quot" tabindex="-1">&quot;Finalmente, alguém que entende de desenvolvimento de elite&quot; <a class="header-anchor" href="#quot-finalmente-alguem-que-entende-de-desenvolvimento-de-elite-quot" aria-label="Permalink to &quot;&amp;quot;Finalmente, alguém que entende de desenvolvimento de elite&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;A maioria dos treinos de petanca se resume a &#39;praticar mais&#39; ou &#39;aprimorar a técnica&#39;. Mas quando você joga há mais de 15 anos, esse não é o problema. O problema é acessar sua técnica sob pressão.&quot;</em></p><p><em>O módulo Zone explicou exatamente o que eu estava vivenciando: pensar demais durante a execução, permanecer no modo analítico quando precisava estar em estado de fluxo. As técnicas práticas para alternar entre os modos foram transformadoras.</em></p><p><em>Este é o primeiro recurso que encontrei que realmente aborda o aspecto mental do jogo em um nível de elite.</em></p></blockquote><p><strong>— Jogador da Seleção Nacional da Suécia</strong></p><hr><h3 id="quot-a-metodologia-de-workshop-transformou-nosso-clube-quot" tabindex="-1">&quot;A metodologia de workshop transformou nosso clube&quot; <a class="header-anchor" href="#quot-a-metodologia-de-workshop-transformou-nosso-clube-quot" aria-label="Permalink to &quot;&amp;quot;A metodologia de workshop transformou nosso clube&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Sou treinador de um clube e usei o guia do Workshop para conduzir uma sessão de jogo mental com nossos 8 melhores jogadores. A estrutura de segurança psicológica e o formato de discussão estruturada criaram conversas que nunca tínhamos tido antes.&quot;</em></p><p><em>Os jogadores se abriram sobre suas autocríticas, suas reações à pressão e seus desafios de comunicação em equipe. Foi incrivelmente impactante. Agora realizamos essas sessões mensalmente, e a cultura da equipe mudou completamente.</em></p></blockquote><p><strong>— Treinador de Clube, Alemanha</strong></p>',14)),r(q),u[2]||(u[2]=i('<hr><h2 id="jogadores-do-torneio" tabindex="-1">Jogadores do torneio <a class="header-anchor" href="#jogadores-do-torneio" aria-label="Permalink to &quot;Jogadores do torneio&quot;">​</a></h2><h3 id="quot-ferramentas-praticas-que-realmente-funcionam-quot" tabindex="-1">&quot;Ferramentas práticas que realmente funcionam&quot; <a class="header-anchor" href="#quot-ferramentas-praticas-que-realmente-funcionam-quot" aria-label="Permalink to &quot;&amp;quot;Ferramentas práticas que realmente funcionam&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Já li livros de psicologia esportiva antes, mas eles sempre são muito genéricos ou muito acadêmicos. O Modelo de Metas e o Modelo de Diário da Academia de Pétanque são exatamente o que eu precisava: práticos, específicos para a petanca e imediatamente utilizáveis.&quot;</em></p><p><em>Usei o modelo de metas e consegui criar um plano de desenvolvimento claro para 3 meses em 30 minutos. O modelo de diário me ajuda a acompanhar não apenas os resultados, mas também o desempenho mental. Essas ferramentas são valiosíssimas.</em></p></blockquote><p><strong>— Jogador de torneio, Espanha</strong></p><hr><h3 id="quot-as-tecnicas-de-mindfulness-funcionam-em-competicoes-quot" tabindex="-1">&quot;As técnicas de mindfulness funcionam em competições&quot; <a class="header-anchor" href="#quot-as-tecnicas-de-mindfulness-funcionam-em-competicoes-quot" aria-label="Permalink to &quot;&amp;quot;As técnicas de mindfulness funcionam em competições&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Eu era cético em relação à atenção plena — parecia muito &#39;leve&#39; para esportes competitivos. Mas as técnicas do módulo de Atenção Plena são práticas e específicas. O reset de 3 respirações, o escaneamento corporal para tensão, os exercícios de foco no momento presente.</em>&quot;</p><p><em>Pratico 10 minutos todas as manhãs e agora consigo usar essas técnicas durante as competições. Quando sinto a pressão aumentar, tenho ferramentas para lidar com ela. Isso fez uma diferença considerável no meu desempenho.</em></p></blockquote><p><strong>— Jogador de torneio, Holanda</strong></p><hr><h3 id="quot-compreender-os-estados-de-fluxo-desbloqueou-meu-potencial-quot" tabindex="-1">&quot;Compreender os estados de fluxo desbloqueou meu potencial&quot; <a class="header-anchor" href="#quot-compreender-os-estados-de-fluxo-desbloqueou-meu-potencial-quot" aria-label="Permalink to &quot;&amp;quot;Compreender os estados de fluxo desbloqueou meu potencial&amp;quot;&quot;">​</a></h3><blockquote><p>&quot;Já tive partidas em que tudo se encaixou perfeitamente — em que eu não pensava, apenas jogava sem parar. Mas eu não sabia como acessar esse estado de forma consistente. O módulo Zone explicou a ciência por trás disso e me deu técnicas práticas.&quot;</p><p><em>Aprender sobre hipofrontalidade transitória, entender a transição entre planejamento e execução, praticar gatilhos de fluxo — esse conhecimento tornou esses estados de desempenho máximo muito mais acessíveis. Estou jogando petanca melhor do que nunca.</em></p></blockquote><p><strong>— Jogador Regional, França</strong></p><hr><h2 id="jogadores-de-equipe" tabindex="-1">Jogadores de equipe <a class="header-anchor" href="#jogadores-de-equipe" aria-label="Permalink to &quot;Jogadores de equipe&quot;">​</a></h2><h3 id="quot-tornou-se-o-colega-de-equipe-que-todos-desejam-quot" tabindex="-1">&quot;Tornou-se o colega de equipe que todos desejam&quot; <a class="header-anchor" href="#quot-tornou-se-o-colega-de-equipe-que-todos-desejam-quot" aria-label="Permalink to &quot;&amp;quot;Tornou-se o colega de equipe que todos desejam&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Eu era tecnicamente forte, mas tinha dificuldades em competições por equipe. O módulo de Dinâmica de Equipe me mostrou que ser um bom jogador de equipe não se resume apenas a fazer bons lançamentos — trata-se de comunicação, confiança e segurança psicológica.&quot;</em></p><p><em>Aprendi a verbalizar confiança, a comunicar estratégias com clareza e a apoiar meus colegas de equipe após erros. Em poucos meses, passei de ser evitado a ser procurado como parceiro. Conquistamos o campeonato regional por equipes este ano.</em></p></blockquote><p><strong>— Jogador de equipe, Itália</strong></p><hr><h3 id="quot-a-estrutura-de-comunicacao-salvou-nossa-parceria-quot" tabindex="-1">&quot;A estrutura de comunicação salvou nossa parceria&quot; <a class="header-anchor" href="#quot-a-estrutura-de-comunicacao-salvou-nossa-parceria-quot" aria-label="Permalink to &quot;&amp;quot;A estrutura de comunicação salvou nossa parceria&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Meu parceiro habitual e eu estávamos enfrentando tensões — estilos de jogo diferentes, comunicação deficiente, frustração crescente. O módulo Jogador de Equipe nos deu uma estrutura para discutir isso de forma construtiva.&quot;</em></p><p><em>Aprendemos sobre padrões de comunicação, sobre como construir confiança e sobre como criar segurança psicológica. Tivemos conversas honestas usando o formato de workshop. Nossa parceria está mais forte do que nunca, e nossos resultados comprovam isso.</em></p></blockquote><p><strong>— Equipe de Duplas, Noruega</strong></p><hr><h2 id="treinadores-e-preparadores-fisicos" tabindex="-1">Treinadores e Preparadores Físicos <a class="header-anchor" href="#treinadores-e-preparadores-fisicos" aria-label="Permalink to &quot;Treinadores e Preparadores Físicos&quot;">​</a></h2><h3 id="quot-e-assim-que-se-parece-o-treinamento-de-elite-quot" tabindex="-1">&quot;É assim que se parece o treinamento de elite&quot; <a class="header-anchor" href="#quot-e-assim-que-se-parece-o-treinamento-de-elite-quot" aria-label="Permalink to &quot;&amp;quot;É assim que se parece o treinamento de elite&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Dou aulas de petanca há 20 anos, focando principalmente na técnica. Mas eu via jogadores com excelente técnica falharem sob pressão. Os módulos de formação me deram a estrutura para abordar o aspecto mental do jogo de forma sistemática.&quot;</em></p><p><em>O guia do Campo de Treinamento me ajudou a estruturar um programa de fim de semana que combinava trabalho técnico com treinamento mental. O feedback dos jogadores foi incrível — eles disseram que foi o treinamento mais valioso que já haviam participado.</em></p></blockquote><p><strong>— Treinador, França</strong></p><hr><h3 id="quot-abordagem-baseada-em-evidencias-para-o-treinamento-mental-quot" tabindex="-1">&quot;Abordagem baseada em evidências para o treinamento mental&quot; <a class="header-anchor" href="#quot-abordagem-baseada-em-evidencias-para-o-treinamento-mental-quot" aria-label="Permalink to &quot;&amp;quot;Abordagem baseada em evidências para o treinamento mental&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;O que mais aprecio é que isto não é apenas conversa motivacional superficial. O conteúdo é baseado em pesquisas reais de psicologia — ciência do estado de fluxo, estudos de mindfulness, psicologia do desempenho. Mas é traduzido em técnicas práticas e aplicáveis.&quot;</em></p><p><em>Utilizo esses módulos como base para o treinamento mental dos meus jogadores de elite. A abordagem estruturada, as estruturas claras, os exercícios práticos — este é um conteúdo de nível profissional.</em></p></blockquote><p><strong>— Psicólogo esportivo e treinador de petanca, Reino Unido</strong></p>',31)),r(p),u[3]||(u[3]=i('<hr><h2 id="temas-comuns" tabindex="-1">Temas comuns <a class="header-anchor" href="#temas-comuns" aria-label="Permalink to &quot;Temas comuns&quot;">​</a></h2><h3 id="o-que-os-jogadores-mais-valorizam" tabindex="-1">O que os jogadores mais valorizam <a class="header-anchor" href="#o-que-os-jogadores-mais-valorizam" aria-label="Permalink to &quot;O que os jogadores mais valorizam&quot;">​</a></h3><p>Com base no feedback, os jogadores destacam consistentemente:</p><ol><li><strong>Conteúdo prático e aplicável</strong> - Não teoria, mas técnicas que você pode usar hoje mesmo.</li><li><strong>Específico para petanca</strong> - Projetado para os desafios únicos da petanca</li><li><strong>Foco em nível de elite</strong> - Aborda o aspecto mental, não a técnica básica.</li><li><strong>Estruturas bem definidas</strong> - Sistemas claros, não conselhos vagos</li><li><strong>Gratuito e acessível</strong> - Sem restrições de pagamento, disponível para todos.</li></ol><h3 id="resultados-mensuraveis" tabindex="-1">Resultados Mensuráveis <a class="header-anchor" href="#resultados-mensuraveis" aria-label="Permalink to &quot;Resultados Mensuráveis&quot;">​</a></h3><p>Os jogadores relatam melhorias em:</p><ul><li>Desempenho e resultados na competição</li><li>Consistência sob pressão</li><li>Tempo de recuperação após erros</li><li>Comunicação e dinâmica de equipe</li><li>Prazer na competição</li><li>resiliência mental</li></ul><h2 id="compartilhe-sua-experiencia" tabindex="-1">Compartilhe sua experiência <a class="header-anchor" href="#compartilhe-sua-experiencia" aria-label="Permalink to &quot;Compartilhe sua experiência&quot;">​</a></h2><p>Você já utilizou os recursos da Pétanque Academy? Gostaríamos muito de saber sobre a sua experiência.</p><p><strong>Envie seu depoimento para:</strong> <a href="mailto:patrik.wiik@gmail.com?subject=Testimonial" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Incluir:</strong></p><ul><li>Seu nível de experiência</li><li>Quais recursos você utilizou?</li><li>Que impacto eles tiveram?</li><li>Podemos compartilhar seu feedback (nome opcional)</li></ul><p>Sua história pode ajudar outros jogadores a descobrir esses recursos.</p><hr><h2 id="comece-agora" tabindex="-1">Comece agora <a class="header-anchor" href="#comece-agora" aria-label="Permalink to &quot;Comece agora&quot;">​</a></h2><p>Pronto para desenvolver seu jogo mental?</p><div class="tip custom-block"><p class="custom-block-title">Comece aqui</p><ul><li><strong>É a sua primeira vez treinando sua mente?</strong> → <a href="/en/education/the-zone/">A Zona</a></li><li><strong>Está com dificuldades para lidar com a pressão?</strong> → <a href="/en/education/mental-strength/">Força Mental</a></li><li><strong>Desafios de equipe?</strong> → <a href="/en/education/team-player/">Dinâmica de Equipe</a></li><li><strong>Quer estrutura?</strong> → <a href="/en/goal-template">Modelo de Meta</a></li></ul></div>',18)),r(p)])}]]);export{u as __pageData,m as default};
